def unit_of_work(metadata=None, timeout=None):
    """
    This function is a decorator for transaction functions that allows extra control over how the transaction is carried out.
    """
    def decorator(func):
        def wrapper(*args, **kwargs):
            driver = kwargs.pop('driver', None)
            if driver is None:
                raise RuntimeError("`driver` must be supplied as a keyword argument when calling the decorated function.")
            with driver.session() as session:
                tx_options = {}
                if metadata is not None:
                    tx_options['metadata'] = metadata
                if timeout is not None:
                    tx_options['timeout'] = timeout
                tx = session.begin_transaction(**tx_options)
                try:
                    result = func(tx, *args, **kwargs)
                    tx.commit()
                    return result
                except Exception:
                    tx.rollback()
                    raise
        return wrapper
    return decorator

