    # Try to locate the underlying sequence used by the collection.
    seq = getattr(self, "_items", None)
    if seq is None:
        seq = getattr(self, "items", None)
    if seq is None:
        # As a last resort, treat the instance itself as an iterable.
        seq = list(self)

    # Most sequences provide a native .index method; use it if available.
    if hasattr(seq, "index"):
        try:
            return seq.index(key)
        except ValueError:
            raise ValueError(f"{key} is not in the sequence")

    # For objects without .index, perform a manual search.
    for idx, item in enumerate(seq):
        if item == key:
            return idx
    raise ValueError(f"{key} is not in the sequence")

