def _legacy_mergeOrderings(orderings):
    """Merge multiple orderings so that within-ordering order is preserved

    Orderings are constrained in such a way that if an object appears
    in two or more orderings, then the suffix that begins with the
    object must be in both orderings.
    """
    # Build directed graph of ordering constraints
    adj = {}
    indeg = {}
    # Record first occurrence order for tiebreaking
    first_occ = {}
    counter = 0
    for ordering in orderings:
        for item in ordering:
            if item not in indeg:
                indeg[item] = 0
                adj[item] = set()
            if item not in first_occ:
                first_occ[item] = counter
                counter += 1
        for u, v in zip(ordering, ordering[1:]):
            if v not in adj[u]:
                adj[u].add(v)
                indeg[v] = indeg.get(v, 0) + 1

    # Topological sort, breaking ties with first occurrence order
    result = []
    # Initially nodes with indegree 0
    zero = [node for node, d in indeg.items() if d == 0]
    # We want deterministic order: sort by first_occ
    from heapq import heapify, heappush, heappop
    heap = []
    for node in zero:
        heappush(heap, (first_occ[node], node))
    while heap:
        _, u = heappop(heap)
        result.append(u)
        for v in sorted(adj[u], key=lambda x: first_occ[x]):
            indeg[v] -= 1
            if indeg[v] == 0:
                heappush(heap, (first_occ[v], v))
    return result

