    The value returned is an `~zope.interface.interfaces.IDeclaration`.
    """
    # Attempt to use the usual attribute that holds the directly provided
    # interfaces.  This is commonly named "__provides__".
    provides = getattr(object, "__provides__", None)

    # If no declares are found, create a dummy Declaration object.
    if provides is None:
        # Provide a minimal declaration class that satisfies the
