def _normalizeargs(sequence, output=None):
    """Normalize declaration arguments

    Normalization arguments might contain Declarions, tuples, or single
    interfaces.

    Anything but individial interfaces or implements specs will be expanded.
    """
    if output is None:
        output = []

    # Lazily import zope.interface utilities if available
    try:
        from zope.interface import Interface, implementedBy
    except Exception:
        Interface = None
        implementedBy = None

    def _process_item(item):
        if item is None:
            return

        # If it's a tuple or list, recurse into each element
        if isinstance(item, (list, tuple)):
            for sub in item:
                _process_item(sub)
            return

        # If we have zope.interface helpers
        if Interface is not None:
            # If the item is an interface class, add it directly
            if isinstance(item, type) and issubclass(item, Interface):
                output.append(item)
                return

            # If the item is a concrete class or other type that
            # implements interfaces, get the interfaces it implements
            if isinstance(item, type):
                try:
                    iface_tuple = implementedBy(item)
                except Exception:
                    # If lookup fails, just add the item itself
                    output.append(item)
                    return
                else:
                    output.extend(iface_tuple)
                    return

        # If zope.interface is not available or the above checks failed,
        # treat the item as an interface-like object or a plain spec
        output.append(item)

    for arg in sequence:
        _process_item(arg)

    return output

