def _get_err_indices(self, coord_name):
    """Return a list of indices in the error vector that correspond to the given coordinate."""
    # First, look for an explicit mapping of coordinate names to error indices.
    if hasattr(self, "_err_index_map"):
        mapping = self._err_index_map.get(coord_name)
        if mapping is None:
            raise ValueError(f"Coordinate {coord_name!r} not found in error mapping.")
        # Handle a few common cases: a slice, a list/tuple or a single integer.
        if isinstance(mapping, (list, tuple)):
            return list(mapping)
        if isinstance(mapping, slice):
            step = mapping.step or 1
            return list(range(mapping.start, mapping.stop, step))
        if isinstance(mapping, int):
            return [mapping]
        raise TypeError("Unsupported type for error index mapping.")

    # If no explicit mapping, try to infer from a list of error names.
    if hasattr(self, "_err_names"):
        indices = [i for i, name in enumerate(self._err_names) if name == coord_name]
        if not indices:
            raise ValueError(f"No error indices found for coordinate {coord_name!r}.")
        return indices

    # If neither mapping nor name list is available, we cannot determine indices.
    raise AttributeError("Cannot determine error indices: no mapping or name list available.")

