def _update_context(self, context):
    # Ensure context has an error dictionary
    if not hasattr(context, "error") or context.error is None:
        context.error = {}

    # Identify graph fields that are not errors
    field_names = []
    for attr in vars(self).keys():
        if attr.startswith("_"):
            continue
        if attr.startswith("error_"):
            continue
        if attr.endswith("_low") or attr.endswith("_high"):
            continue
        field_names.append(attr)

    # Process each error attribute
    for attr_name, value in vars(self).items():
        if not attr_name.startswith("error_"):
            continue

        # Expect format error_<field>_<type>, e.g., error_E_low
        try:
