def fill(self, coord, weight=1):
    """Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    # Ensure the coordinate is a tuple for indexing
    if not isinstance(coord, (tuple, list)):
        coord = (coord,)
    if len(coord) != len(self.edges):
        raise ValueError(f"Coordinate dimensionality {len(coord)} does not match histogram {len(self.edges)}")
    indices = []
    for dim, val in enumerate(coord):
        edge = self.edges[dim]
        # Reject if value is outside the range
        if val < edge[0] or val >= edge[-1]:
            return
        # Find bin index (linear search)
        for i in range(len(edge) - 1):
            if edge[i] <= val < edge[i + 1]:
                indices.append(i)
                break
        else:
            # Should not happen because of the earlier check, but guard anyway
            return
    # Increment the corresponding bin by weight
    self.bins[tuple(indices)] += weight

