def format(self, sql, params):
    # Support both str and bytes SQL queries
    is_bytes = isinstance(sql, (bytes, bytearray))
    if isinstance(params, dict):
        # Named parameters: replace :name with @name
        out_params = {}
        out_sql = sql
        for key, value in params.items():
            if is_bytes:
                search = b':' + key.encode() if isinstance(key, str) else b':' + str(key).encode()
                replace = b'@' + key.encode() if isinstance(key, str) else b'@' + str(key).encode()
                out_sql = out_sql.replace(search, replace)
                out_params[replace] = value
            else:
                search = f":{key}"
                replace = f"@{key}"
                out_sql = out_sql.replace(search, replace)
                out_params[replace] = value
        return out_sql, out_params
    else:
        # Ordinal parameters: replace ? with @param1, @param2, ...
        out_sql = sql
        idx = 1
        for _ in params:
            if is_bytes:
                out_sql = out_sql.replace(b'?', b'@param' + str(idx).encode(), 1)
            else:
                out_sql = out_sql.replace('?', f"@param{idx}", 1)
            idx += 1
        return out_sql, list(params)

