def validate(self, path):
    """Validate OCFL object at path or pyfs root.

    Returns True if valid (warnings permitted), False otherwise.
    """
    import os
    import json

    # Resolve the root directory
    if hasattr(path, "path"):
        root = path.path
    else:
        root = str(path)

    if not os.path.isdir(root):
        return False

    # Required structural elements
    required_dirs = ["_content"]
    required_files = ["_manifest.json", "_digests.csv"]
    for d in required_dirs:
        if not os.path.isdir(os.path.join(root, d)):
            return False
    for f in required_files:
        if not os.path.isfile(os.path.join(root, f)):
            return False

    # _content should not be empty
    content_dir = os.path.join(root, "_content")
    if not any(os.scandir(content_dir)):
        return False

    # Basic sanity checks on _manifest.json
    try:
        with open(os.path.join(root, "_manifest.json"), "r", encoding="utf-8") as mf:
            data = json.load(mf)
        # The manifest should contain at least 'layout_version' and 'object_path'
        if not isinstance(data, dict):
            return False
        if "layout_version" not in data or "object_path" not in data:
            return False
        # Optionally check 'layout_version' value
        if not isinstance(data.get("layout_version"), int):
            return False
    except Exception:
        return False

    # The _digests.csv file can optionally be parsed for sanity;
    # no strict validation required for now.
    return True

