def validate(self, path):
    """Validate OCFL object at path or pyfs root.

    Returns True if valid (warnings permitted), False otherwise.
    """
    try:
        # Resolve path to a string
        if isinstance(path, str):
            root = path
        else:
            root = str(path)

        # Check for required .ocfl_version file
        version_file = os.path.join(root, '.ocfl_version')
        if not os.path.isfile(version_file):
            return False

        with open(version_file, 'r') as vf:
            version = vf.read().strip()
        if not version:
            return False

        # Ensure .ocfl directory exists
        ocfl_dir = os.path.join(root, '.ocfl')
        if not os.path.isdir(ocfl_dir):
            return False

        # The metadata directory must exist and contain at least one .manifest file
        metadata_dir = os.path.join(ocfl_dir, 'metadata')
        if not os.path.isdir(metadata_dir):
            return False
        manifests = [f for f in os.listdir(metadata_dir) if f.endswith('.manifest')]
        if not manifests:
            return False
        for m in manifests:
            m_path = os.path.join(metadata_dir, m)
            if not os.path.isfile(m_path):
                return False

        # Ensure objects directory exists
        objects_dir = os.path.join(ocfl_dir, 'objects')
        if not os.path.isdir(objects_dir):
            return False

        # Validate each object and its versions
        object_oids = [oid for oid in os.listdir(objects_dir)
                       if os.path.isdir(os.path.join(objects_dir, oid))]
        if not object_oids:
            return False
        for oid in object_oids:
            oid_dir = os.path.join(objects_dir, oid)
            version_dirs = [v for v in os.listdir(oid_dir)
                            if os.path.isdir(os.path.join(oid_dir, v))]
            if not version_dirs:
                return False
            for v in version_dirs:
                v_dir = os.path.join(oid_dir, v)
                # Every version should contain a manifest and a blob directory
                if not os.path.isdir(os.path.join(v_dir, 'objects')):
                    return False
                blobs = os.listdir(v_dir)
                if not blobs:
                    return False

        return True
    except Exception:
        return False

