    """Validate OCFL object at path or pyfs root.
    Returns True if valid (warnings permitted), False otherwise.
    """
    try:
        # Ensure the object root exists
        if not self.fs.exists(path):
            return False

        # Verify the presence of the manifest file
        manifest_path = os.path.join(path, 'manifest.json')
        if not self.fs.exists(manifest_path):
            return False

        # Load and parse manifest
        with self.fs.open(manifest_path, 'r') as f:
            manifest = json.load(f)

        # Basic manifest validation
        if not isinstance(manifest, dict):
            return False
        if 'ocfl_version' not in manifest:
            return False

        # Ensure the content directory exists
        content_dir = os.path.join(path, 'content')
        if not self.fs.isdir(content_dir):
            return False

        # Recursively walk the content tree and ensure files exist
        def walk(dir_path):
            for name in self.fs.listdir(dir_path):
                sub_path = os.path.join(dir_path, name)
                if self.fs.isdir(sub_path):
                    if not walk(sub_path):
                        return False
                else:
                    # Files in content should be listed in the manifest; if not, allow a warning
                    if not any(sub_path in v for v in manifest.values()):
                        pass
            return True

        if not walk(content_dir):
            return False

        return True
    except Exception:
        return False

