def validate(self, path):
    """Validate OCFL object at path or pyfs root.

    Returns True if valid (warnings permitted), False otherwise.
    """
    # Ensure path is a directory
    if not os.path.isdir(path):
        return False

    # Required top-level files
    required_files = ['.ocfl-info', '.ocfl-layout', '.ocfl-manifest']
    parsed_files = {}
    for fname in required_files:
        fpath = os.path.join(path, fname)
        if not os.path.isfile(fpath):
            return False
        try:
            with open(fpath, 'r', encoding='utf-8') as f:
                parsed_files[fname] = json.load(f)
        except (OSError, json.JSONDecodeError):
            return False

    # Basic checks on parsed data
    # .ocfl-info should contain at least 'root' and 'title' (flexible)
    if not isinstance(parsed_files['.ocfl-info'], dict):
        return False
    ocfl_info = parsed_files['.ocfl-info']
    if 'root' not in ocfl_info:
        return False

    # .ocfl-layout should define layout parameters (e.g., "layout")
    if not isinstance(parsed_files['.ocfl-layout'], dict):
        return False
    ocfl_layout = parsed_files['.ocfl-layout']
    if 'layout' not in ocfl_layout:
        return False

    # .ocfl-manifest should be a dict mapping file paths to hashes
    if not isinstance(parsed_files['.ocfl-manifest'], dict):
        return False
    ocfl_manifest = parsed_files['.ocfl-manifest']
    for rel_path in ocfl_manifest.keys():
        full_path = os.path.join(path, rel_path)
        if not os.path.exists(full_path):
            return False

    # Ensure at least one version directory exists
    version_dir_found = False
    for entry in os.listdir(path):
        entry_path = os.path.join(path, entry)
        if os.path.isdir(entry_path) and re.match(r'^[0-9a-fA-F]+$', entry):
            version_dir_found = True
            break
    if not version_dir_found:
        return False

    # All checks passed
    return True

