def status_str(self, prefix=''):
    """Return string of validator status, with optional prefix."""
    # Collect non-private attributes which likely hold status information
    status_parts = []
    for key in sorted(vars(self)):
        if key.startswith('_'):
            continue
        value = getattr(self, key)
        # Convert numpy arrays and other non-unicode objects to string
        try:
            status_parts.append(f"{key}={value!r}")
        except Exception:
            status_parts.append(f"{key}={str(value)!r}")
    return prefix + ', '.join(status_parts)

