def status_str(self, prefix=''):
    """Return string of validator status, with optional prefix."""
    # Determine the status representation
    status = getattr(self, 'status', None)
    if status is None:
        return prefix

    # If status is a dictionary, format key-value pairs
    if isinstance(status, dict):
        parts = []
        for key, val in status.items():
            # Convert each value to string, handling nested lists/dicts
            if isinstance(val, dict):
                val_str = ', '.join(f'{k}={v}' for k, v in val.items())
            elif isinstance(val, (list, tuple)):
                val_str = ', '.join(str(vv) for vv in val)
            else:
                val_str = str(val)
            parts.append(f'{key}={val_str}')
        status_str = ', '.join(parts)

    # If status is a list or tuple, join elements
    elif isinstance(status, (list, tuple)):
        status_str = ', '.join(str(v) for v in status)

    # Otherwise convert status directly to string
    else:
        status_str = str(status)

    # Prepend the optional prefix
    return f'{prefix}{status_str}'

