    # Basic sanity checks for each plugin entry
    for idx, plugin in enumerate(plugins):
        if not isinstance(plugin, dict):
            raise ValueError(f"Plugin #{idx} must be a dictionary")
        required_keys = {"name", "path", "method"}
        missing = required_keys - plugin.keys()
        if missing:
            raise ValueError(f"Plugin #{idx} is missing keys: {', '.join(missing)}")

    # Placeholder for any additional checks based on spec_ver
    # (e.g., validating exporter, configuration, etc.)

    return spec_ver

