    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    logical_map = {}
    try:
        state = inventory["versions"][version]["state"]
        state_files = state.get("files", {})
    except Exception:
        return logical_map

    for _, file_info in state_files.items():
        logical_path = file_info.get("logical_path")
        content_name = file_info.get("content")
        if not logical_path or not content_name:
            continue
        content_spec = inventory.get("info", {}).get("content", {}).get(content_name, {})
        content_file = content_spec.get("file")
        if not content_file:
            continue
        logical_map.setdefault(logical_path, set()).add(content_file)

    return logical_map

