def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    # Ensure fixity is a dictionary
    if not isinstance(fixity, dict):
        raise ValueError(f"Expected fixity to be a dict, got {type(fixity).__name__}")
    # Convert manifest files to a set for fast lookup
    manifest_set = set(manifest_files)
    if not isinstance(manifest_set, set):
        raise ValueError("manifest_files must be an iterable of file names")
    # Regular expression for hexadecimal string
    import re
    hex_re = re.compile(r'^[a-fA-F0-9]+$')
    # Allowed hash algorithm names (common ones)
    allowed_algorithms = {
        'md5', 'sha1', 'sha256', 'sha512', 'sha3-256', 'sha3-512', 'sha224', 'sha384'
    }
    # Validate each entry in the fixity block
    for file_name, hashes in fixity.items():
        if file_name not in manifest_set:
            raise ValueError(f"Fixity references unknown file '{file_name}' not present in manifest")
        if not isinstance(hashes, dict):
            raise ValueError(f"Fixity entry for file '{file_name}' must be a dict of hash algorithms")
        # If no hashes provided, warn but allow?
        if not hashes:
            raise ValueError(f"Fixity entry for file '{file_name}' contains no hash entries")
        for alg, value in hashes.items():
            if alg not in allowed_algorithms:
                raise ValueError(f"Unsupported hash algorithm '{alg}' for file '{file_name}'")
            if not isinstance(value, str) or not hex_re.fullmatch(value):
                raise ValueError(f"Hash value for file '{file_name}' and algorithm '{alg}' must be a hex string")
    # Ensure no files in manifest are missing from fixity? (Optional)
    # If this is required, uncomment the following:
