def validate_fixity(self, fixity, manifest_files):
    """
    Validate the structure of a fixity block and ensure that all referenced
    files are present in the provided list of manifest files.

    Expected formats for `fixity`:
        1. A mapping from file paths to checksums:
               {"path/to/file1": "sha256:abc123...", ...}
        2. A list of dictionaries each containing a 'path' and 'checksum':
               [{"path": "path/to/file1", "checksum": "sha256:abc123..."},
                {"path": "path/to/file2", "checksum": "sha256:def456..."}]

    Parameters
    ----------
    fixity : dict or list
        The fixity block extracted from the inventory.
    manifest_files : iterable
        Collection of file paths present in the manifest (relative or absolute).

    Raises
    ------
    ValueError
        If the fixity block is not a valid structure or references files not
        present in the manifest, or if checksums are not strings.
    """
    # Normalize manifest files into a set for O(1) lookups
    expected_files = set(manifest_files)

    # Helper to raise a formatted error
    def _error(msg, key=None):
        if key is not None:
            msg = f"{msg} (key: {key})"
        raise ValueError(msg)

    # Validate primary structure
    if isinstance(fixity, dict):
        if not fixity:
            _error("Fixity block must contain at least one entry")
        for file_ref, checksum in fixity.items():
            if file_ref not in expected_files:
                _error(f"Fixity references unknown file '{file_ref}'", file_ref)
            if not isinstance(checksum, str):
                _error(f"Checksum for '{file_ref}' must be a string", file_ref)
    elif isinstance(fixity, list):
        seen = set()
        if not fixity:
            _error("Fixity list must contain at least one entry")
        for idx, entry in enumerate(fixity):
            if not isinstance(entry, dict):
                _error(f"Entry at index {idx} is not a dictionary")
            if 'path' not in entry or 'checksum' not in entry:
                _error(f"Entry at index {idx} missing 'path' or 'checksum'")
            file_ref = entry['path']
            checksum = entry['checksum']
            if file_ref not in expected_files:
                _error(f"Fixity references unknown file '{file_ref}'", file_ref)
            if not isinstance(checksum, str):
                _error(f"Checksum for '{file_ref}' must be a string", file_ref)
            if file_ref in seen:
                _error(f"Duplicate fixity entry for file '{file_ref}'")
            seen.add(file_ref)
    else:
        _error("Fixity block must be a dictionary or a list of dictionaries")

    # If no exception was raised, the block is considered valid
    return True

