def select_filenames_by_prefix(prefix, files):
    result = []
    for f in files:
        name = f.rsplit('/', 1)[-1]
        if name == f:  # no slash found, try backslash
            name = f.rsplit('\\', 1)[-1]
        if name.startswith(prefix):
            result.append(f)
    return result

