def _explore_folder(folder):
    """
    Get packages' data from folder

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    folder : str
        Folder of the package
    Returns
    -------
    dict
        Mapping from XML base name to list of file paths belonging to that package.
    """
    import os

    # Ensure the provided path is a directory
    if not os.path.isdir(folder):
        return {}

    # Collect all files in the given folder (non‑recursive)
    files_in_folder = []
    for item in os.listdir(folder):
        full_path = os.path.join(folder, item)
        if os.path.isfile(full_path):
            files_in_folder.append(full_path)

    # Group files by their basename without extension
    groups = {}
    for file_path in files_in_folder:
        base_name, _ = os.path.splitext(os.path.basename(file_path))
        groups.setdefault(base_name, []).append(file_path)

    # Keep only groups that contain at least one XML file
    result = {
        base: paths
        for base, paths in groups.items()
        if any(os.path.splitext(p)[1].lower() == ".xml" for p in paths)
    }

    return result

