def add_asset(self, basename, file_path):
    # Ensure the assets dictionary exists
    if not hasattr(self, "assets"):
        self.assets = {}
    # Extract the extension from the file_path
    if '.' in file_path:
        name_part, ext = file_path.rsplit('.', 1)
        ext = '.' + ext
    else:
        ext = ''
    # Build the full key (basename + extension)
    full_key = f"{basename}{ext}"
    # Initialize the dictionary for this basename if it doesn't exist
    if basename not in self.assets:
        self.assets[basename] = {}
    # Add or update the file_path for this full key
    self.assets[basename][full_key] = file_path

