def _extract_number_and_supplment_from_issue_element(issue):
    import re
    s = issue.strip().lower()
    if not s:
        return None, None
    # Standardise punctuation
    s_clean = re.sub(r'[.,()\-]', ' ', s)
    tokens = [t for t in s_clean.split() if t]
    if not tokens:
        return None, None

    # Detect number (or range) at start
    number = None
    if re.match(r'^\d+(?:-\d+)?$', tokens[0]):
        number = tokens[0]
        tokens = tokens[1:]

    # Handle a leading "sX" style (e.g., "s2")
    if tokens and re.match(r'^s\d+$', tokens[0]):
        try:
            suppl = int(tokens[0][1:])
        except ValueError:
            suppl = None
        else:
            tokens = tokens[1:]
    else:
        suppl = None

    # Search for typical supplement indicators
    for i, tok in enumerate(tokens):
        if tok in ("suppl", "supp", "spe", "suppl.", "supp.", "spe.", "suppli"):
            # check for following number or range
            if i + 1 < len(tokens):
                nxt = tokens[i + 1]
                if nxt.isdigit():
                    try:
                        suppl = int(nxt)
                        break
                    except ValueError:
                        pass
                # range like "1-2"
                if re.match(r'^\d+-\d+$', nxt):
                    suppl = nxt
                    break
            # no qualifier – treat as flag
            suppl = True
            break

    return number, suppl

