def get_versions():
    """
    Get version information or return default if unable to do so.
    Attempts to read from an embedded VERSION file, package metadata,
    or git tags. If all fail, returns a default value.

    Returns a dict with keys:
        "full-revisionid": full git commit hash or None
        "version": short readable version string
    """
    import os
    import subprocess

    # 1. Try reading a VERSION file in the same directory
    version_file = os.path.join(os.path.dirname(__file__), "VERSION")
    if os.path.isfile(version_file):
        try:
            with open(version_file, "r", encoding="utf-8") as f:
                v = f.read().strip()
                if v:
                    return {"full-revisionid": None, "version": v}
        except Exception:
            pass

    # 2. Try package metadata (Python >=3.8)
    try:
        from importlib.metadata import version as _pkg_version  # type: ignore
        # Use the module name as the distribution name if available
        distro_name = __package__ or "unknown"
        v = _pkg_version(distro_name)
        if v:
            return {"full-revisionid": None, "version": v}
    except Exception:
        pass

    # 3. Try Git to determine a version
    try:
        # Human‑readable tag or commit
        result = subprocess.run(
            ["git", "describe", "--tags", "--always", "--dirty"],
            capture_output=True,
            text=True,
            check=True,
        )
        v = result.stdout.strip()
        if v:
            # Full commit hash for reference
            rev = subprocess.run(
                ["git", "rev-parse", "HEAD"],
                capture_output=True,
                text=True,
                check=True,
            ).stdout.strip()
            return {"full-revisionid": rev, "version": v}
    except Exception:
        pass

    # Fallback if all methods fail
    return {"full-revisionid": None, "version": "0+unknown"}

