def render(pieces, style):
    """Render the given version pieces into the requested style."""
    # Helper functions for escaping and formatting
    def escape_html(text):
        return text.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;")

    def format_plain(value):
        return value

    def format_html(value, token_type):
        escaped = escape_html(value)
        return f'<span class="{token_type}">{escaped}</span>'

    def format_markdown(value, token_type):
        if token_type == "code":
            return f"`{value}`"
        if token_type == "comment":
            return f"// {value}"
        return value

    # Decide which formatting function to use
    if style == "plain":
        formatter = format_plain
    elif style == "html":
        formatter = lambda v, t: format_html(v, t)
    elif style == "markdown":
        formatter = lambda v, t: format_markdown(v, t)
    else:
        # Fallback to plain if unknown style
        formatter = format_plain

    rendered_parts = []
    for piece in pieces:
        # Each piece is expected to be a dict with 'value' and optional 'type'
        value = piece.get("value", "")
        token_type = piece.get("type", "code")
        if style == "plain":
            rendered_parts.append(formatter(value))
        else:
            rendered_parts.append(formatter(value, token_type))

    return "".join(rendered_parts)

