def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    if not version:
        return "1"
    parts = [p for p in version.split(".") if p != ""]
    if not parts:
        return "1"
    try:
        # Increment the last component
        last = parts[-1]
        width = len(last)
        incremented = int(last) + 1
        new_last = str(incremented)
        if len(new_last) < width:
            new_last = new_last.rjust(width, "0")
        parts[-1] = new_last
    except ValueError:
        # If the last component isn't a number, try appending ".1"
        if parts:
            parts.append("1")
        else:
            parts = ["1"]
    return ".".join(parts)

