            except Exception as exc:
                raise ValueError(f'Failed to parse inventory JSON in {vdir}: {exc}')

        # Ensure every file from the root inventory appears in this version
        for fname, root_digest in root_inv.items():
            if fname not in version_inv:
                raise ValueError(f'File "{fname}" missing in inventory for version "{vdir}"')
