def find_path_type(path):
    """Return a string indicating the type of thing at the given path.

    Return values:
        'root'   - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file'   - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    import os
    # Basic existence and type checks
    if not os.path.exists(path):
        return f"does not exist: {path}"
    if os.path.isfile(path):
        return 'file'
    if not os.path.isdir(path):
        return f"not a directory: {path}"

    # Look for Namaste files that start with "0="
    try:
        entries = os.listdir(path)
    except OSError as exc:
        return str(exc)

    namaste_candidates = [e for e in entries if e.startswith('0=')]
    if not namaste_candidates:
        # No Namaste file -> treat as a plain fileish directory
        return 'file'

    # Read the first suitable Namaste file
    namaste_path = os.path.join(path, namaste_candidates[0])
    try:
        with open(namaste_path, 'rb') as f:
            data = f.read(128)  # read enough bytes for detection
    except OSError as exc:
        return str(exc)

    # Detect OCFL repository root vs object root
    if b'OCFL' in data[:4]:
        # Common prefix for OCFL containers
        if b'Object' in data[:64]:
            return 'object'
        else:
            return 'root'
    # Unknown or unsupported Namaste file
    return f"unknown Namaste content: {data[:16]}"

