def amend_bzparams(self, params, bug_ids):
    """Amend the Bugzilla params"""
    # Ensure the params argument is a dictionary
    if not isinstance(params, dict):
        raise TypeError("params must be a dict")
    # Normalize bug_ids to a list
    if bug_ids is None:
        return params
    if isinstance(bug_ids, (str, int)):
        bug_ids = [bug_ids]
    elif isinstance(bug_ids, (list, tuple, set)):
        bug_ids = list(bug_ids)
    else:
        raise TypeError("bug_ids must be a string, int, list, tuple, or set")
    # Remove duplicates while preserving order
    seen = set()
    uniq_bug_ids = []
    for bid in bug_ids:
        if bid not in seen:
            seen.add(bid)
            uniq_bug_ids.append(bid)
    # Set the 'ids' key in params
    params["ids"] = uniq_bug_ids
    return params

