def deep_merge_nodes(nodes):
    """
    Deep merge YAML nodes represented as tuples of (ScalarNode, Node) pairs.
    Duplicate keys are merged recursively if both values are MappingNode instances;
    otherwise the later value wins.

    Parameters
    ----------
    nodes : list of tuple
        The input list of (key_node, value_node) tuples.  Each key_node is a
        ScalarNode and each value_node is either a MappingNode or any other
        Node type.

    Returns
    -------
    list
        A new list of (key_node, value_node) tuples with merged values.
    """
    from ruamel.yaml.nodes import MappingNode, ScalarNode

    def merge_mapping_nodes(m1, m2):
        """Recursively merge two MappingNode objects."""
        merged = {}
        # Process entries from the first mapping
        for k_node, v_node in m1.value:
            k = k_node.value
            merged[k] = (k_node, v_node)

        # Merge entries from the second mapping, overriding where necessary
        for k_node, v_node in m2.value:
            k = k_node.value
            if k in merged:
                _, existing_v = merged[k]
                if isinstance(existing_v, MappingNode) and isinstance(v_node, MappingNode):
                    merged_v = merge_mapping_nodes(existing_v, v_node)
                    merged[k] = (k_node, merged_v)
                else:
                    merged[k] = (k_node, v_node)
            else:
                merged[k] = (k_node, v_node)

        # Convert back to a list of tuples while preserving insertion order
        merged_list = [(k_node, v_node) for k_node, v_node in merged.values()]
        return MappingNode(tag=m1.tag, value=merged_list)

    merged_dict = {}
    for key_node, val_node in nodes:
        key = key_node.value if isinstance(key_node, ScalarNode) else None
        if key is None:
            continue  # skip non‑scalar keys

        if key in merged_dict:
            existing_key_node, existing_val_node = merged_dict[key]
            if isinstance(existing_val_node, MappingNode) and isinstance(val_node, MappingNode):
                merged_val = merge_mapping_nodes(existing_val_node, val_node)
                merged_dict[key] = (existing_key_node, merged_val)
            else:
                merged_dict[key] = (key_node, val_node)  # later value wins
        else:
            merged_dict[key] = (key_node, val_node)

    return list(merged_dict.values())

