    Merge nested ruamel.yaml node structures by key, handling duplicate keys.
    Keys are ScalarNodes; values can be MappingNodes or other node types.
    '''
    def is_mapping_node(node):
        return hasattr(node, 'tag') and node.tag.startswith('tag:yaml.org,2002:map')

    def _merge_node(a, b):
        # If both are mapping nodes, deep merge their content
        if is_mapping_node(a) and is_mapping_node(b):
            merged_vals = deep_merge_nodes(a.value + b.value)
            return type(b)(tag=b.tag, value=merged_vals)
        # otherwise, the later value wins
        return b

    merged = {}
    for key_node, val_node in nodes:
        key = getattr(key_node, 'value', None)
        if key in merged:
            merged[key] = _merge_node(merged[key], val_node)
        else:
