    # Preserve original key ordering: first occurrence of each key
    seen = set()
    result = []
    for key_node, _ in nodes:
        key = getattr(key_node, 'value', None)
        if key not in seen:
            seen.add(key)
            result.append((key_node, merged[key]))
    return result

