def size_to_bytes(size: str) -> int:
    """Convert human readable file size to bytes.

    Resulting value is an approximation as input value is in most case rounded.

    Args:
        size: A string representing a human readable file size (eg: '500K')

    Returns:
        A decimal representation of file size

        Examples::

            >>> size_to_bytes("500")
            500
            >>> size_to_bytes("1K")
            1000
    """
    if not isinstance(size, str):
        raise TypeError("size must be a string")

    s = size.strip()
    if not s:
        raise ValueError("size string is empty")

    # Define the unit factors (decimal)
    units = {
        'B': 1,
        'K': 1000,
        'M': 1000 ** 2,
        'G': 1000 ** 3,
        'T': 1000 ** 4,
        'P': 1000 ** 5,
        'E': 1000 ** 6,
    }

    # Detect a unit suffix
    if s[-1].isalpha():
        unit = s[-1].upper()
        factor = units.get(unit)
        if factor is None:
            raise ValueError(f"Unsupported unit '{unit}' in size '{size}'")
        number_part = s[:-1].strip()
        if not number_part:
            raise ValueError(f"Missing numeric part in size '{size}'")
        try:
            number = float(number_part)
        except ValueError as exc:
            raise ValueError(f"Invalid numeric value '{number_part}' in size '{size}'") from exc
        return int(round(number * factor))
    else:
        # No unit, interpret as plain number of bytes
        try:
            return int(s)
        except ValueError:
            try:
                return int(float(s))
            except ValueError:
                raise ValueError(f"Invalid size format: '{size}'")

