def split(s, platform='this'):
    """Split a command line string into arguments for POSIX or Windows."""
    s = str(s)

    # Resolve platform if auto
    if platform == 'this':
        import os
        platform = 0 if os.name == 'nt' else 1

    # Normalise platform value
    try:
        platform = int(platform)
    except Exception:
        platform = 1 if platform == 1 else 0

    # POSIX: use the standard shlex split
    if platform == 1:
        import shlex
        return shlex.split(s)

    # Windows: emulate cmd.exe quoting rules with shlex posix=False
    elif platform == 0:
        import shlex
        return shlex.split(s, posix=False)

    raise ValueError(f'Unsupported platform: {platform}')

