def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    '''
    results = {}
    error_records = []
    json = __import__('json')
    for filename in config_filenames:
        try:
            with open(filename, 'r') as f:
                raw = f.read()
            try:
                cfg = json.loads(raw)
            except Exception as e:
                record = logging.LogRecord(
                    name='load_configurations',
                    level=logging.ERROR,
                    pathname=filename,
                    lineno=0,
                    msg=f'Error parsing {filename}: {e}',
                    args=(),
                    exc_info=None
                )
                error_records.append(record)
                continue
            if overrides and isinstance(cfg, dict):
                cfg.update(overrides)
            elif overrides:
                record = logging.LogRecord(
                    name='load_configurations',
                    level=logging.ERROR,
                    pathname=filename,
                    lineno=0,
                    msg=f'Cannot apply overrides to non-dict config in {filename}',
                    args=(),
                    exc_info=None
                )
                error_records.append(record)
                continue
            if resolve_env:
                import re
                pattern = re.compile(r'\$\{([^}]+)\}')
                def repl(match):
                    var = match.group(1)
                    return __import__('os').environ.get(var, match.group(0))
                def resolve(obj):
                    if isinstance(obj, str):
                        return pattern.sub(repl, obj)
                    if isinstance(obj, dict):
                        return {k: resolve(v) for k, v in obj.items()}
                    if isinstance(obj, list):
                        return [resolve(v) for v in obj]
                    return obj
                cfg = resolve(cfg)
            results[filename] = cfg
        except Exception as e:
            record = logging.LogRecord(
                name='load_configurations',
                level=logging.ERROR,
                pathname=filename,
                lineno=0,
                msg=f'Error loading {filename}: {e}',
                args=(),
                exc_info=None
            )
            error_records.append(record)
    return results, error_records

