def scale(self, other=None, recompute=False):
    """Compute or set scale (integral of the histogram).

    If *other* is ``None``, return scale of this histogram.
    If its scale was not computed before,
    it is computed and stored for subsequent use
    (unless explicitly asked to *recompute*).
    Note that after changing (filling) the histogram
    one must explicitly recompute the scale
    if it was computed before.

    If a float *other* is provided, rescale self to *other*.

    Histograms with scale equal to zero can't be rescaled.
    :exc:`.LenaValueError` is raised if one tries to do that.
    """
    # Helper to compute scale if not cached
    def _compute_scale():
        # Try standard integral calculation
        try:
            # If histogram has an integral method, use it
            if hasattr(self, "integral"):
                return self.integral()
        except Exception:
            pass
        # Fallback: sum over bin contents
        try:
            # If histogram stores bins in a list/tuple named _bins
            if hasattr(self, "_bins") and self._bins:
                return sum(bin.content for bin in self._bins)
        except Exception:
            pass
        # Final fallback: assume histogram is iterable of bin contents
        try:
            return sum(self)
        except Exception:
            pass
        # If all fails, return zero scale
        return 0.0

    if other is None:
        # Return cached scale or compute it
        if not getattr(self, "_scale", None) or recompute:
            self._scale = _compute_scale()
        return self._scale

    # Rescale to a new total weight (other must be a float)
    # Ensure other is a numeric value
    try:
        new_scale = float(other)
    except Exception as exc:
        raise TypeError("Other must be a numeric scalar") from exc

    current_scale = self.scale()
    if current_scale == 0:
        raise LenaValueError("Histograms with scale equal to zero can't be rescaled.")

    factor = new_scale / current_scale
    # Apply scaling to each bin
    if hasattr(self, "_bins") and self._bins:
        for bin in self._bins:
            try:
                # Assume bin has content and error attributes and setters
                bin.setContent(bin.content * factor)
                # If stored errors, scale them by factor as well
                if hasattr(bin, "setError"):
                    bin.setError(bin.error * factor)
            except Exception:
                # Fallback: try attribute assignment
                try:
                    bin.content = getattr(bin, "content", 0.0) * factor
                    if hasattr(bin, "error"):
                        bin.error = getattr(bin, "error", 0.0) * factor
                except Exception:
                    # Give up on this bin
                    pass
