    """
    Compute or set scale (integral of the histogram).

    If *other* is ``None``, return scale of this histogram.
    If its scale was not computed before, it is computed and stored for subsequent use
    (unless explicitly asked to *recompute*).
    Note that after changing (filling) the histogram one must explicitly recompute the scale
    if it was computed before.

    If a float *other* is provided, rescale self to *other*.

    Histograms with scale equal to zero can't be rescaled.
    :exc:`.LenaValueError` is raised if one tries to do that.
    """
    # Helper to compute integral from content and width if available
    def _integral():
        # Try attributes that may hold bin contents and widths
        if hasattr(self, "_bin_contents") and hasattr(self, "_bin_widths"):
            return sum(c * w for c, w in zip(self._bin_contents, self._bin_widths))
        if hasattr(self, "contents"):
            return sum(self.contents)
        # Fallback: sum over iterable interface
        try:
            return sum(self)
        except Exception:
            raise Exception("Unable to compute histogram integral: missing content data")

    # --- Get or compute scale -------------------------------------------------
    if other is None:
        if getattr(self, "_scale", None) is None or recompute:
            self._scale = _integral()
        return self._scale

    # --- Rescale histogram ----------------------------------------------------
    new_scale = float(other)
    current_scale = self.scale(recompute=True)  # ensure we use latest scale
    if current_scale == 0:
        raise Exception("Cannot rescale histogram with zero integral")

    factor = new_scale / current_scale

    # Update bin contents
    if hasattr(self, "_bin_contents") and hasattr(self, "_bin_widths"):
        self._bin_contents = [c * factor for c in self._bin_contents]
    elif hasattr(self, "contents"):
        self.contents = [c * factor for c in self.contents]
    else:
        # Generic iterable; modify in place if mutable
        try:
            for i, val in enumerate(self):
                self[i] = val * factor
        except Exception:
            raise Exception("Unable to rescale histogram: missing content data")

    self._scale = new_scale
    # Nothing is returned for mutation semantics.

def hist_to_graph(hist, make_value=None, get_coordinate="left",
                  field_names=("x", "y"), scale=None):
    """
    Convert a :class:`.histogram` to a :class:`.graph`.

    *make_value* is a function to set the value of a graph's point.
    By default it is bin content.
    *make_value* accepts a single value (bin content) without context.

    This option could be used to create graph's error bars.
    For example, to create a graph with errors
    from a histogram where bins contain
    a named tuple with fields *mean*, *mean_error* and a context
    one could use

    >>> make_value = lambda bin_: (bin_.mean, bin_.mean_error)

    *get_coordinate* defines what the coordinate
    of a graph point created from a histogram bin will be.
    It can be "left" (default), "right" and "middle".

    *field_names* set field names of the graph. Their number
    must be the same as the dimension of the result.
    For a *make_value* above they would be
    *("x", "y_mean", "y_mean_error")*.

    *scale* becomes the graph's scale (unknown by default).
    If it is ``True``, it uses the histogram scale.

    *hist* must contain only numeric bins (without context)
    or *make_value* must remove context when creating a numeric graph.

    Return the resulting graph.
    """
    # Simple internal graph representation
    class Graph:
        def __init__(self, field_names):
            self.field_names = list(field_names)
            self.points = []  # list of tuples of values
            self.scale = None
        def add_point(self, *values):
            if len(values) != len(self.field_names):
                raise ValueError("Point values do not match field names")
            self.points.append(tuple(values))
        def __repr__(self):
            return f"Graph(fields={self.field_names!r}, points={self.points!r}, scale={self.scale!r})"

    if get_coordinate not in {"left", "right", "middle"}:
        raise ValueError("get_coordinate must be 'left', 'right' or 'middle'")
    if make_value is None:
        make_value = lambda bin_content: bin_content

    graph = Graph(field_names)

    # Determine coordinate attribute name
    coord_attr = {
        "left": "lower_edge",
        "right": "upper_edge",
        "middle": "center",
    }[get_coordinate]

    # Iterate over histogram bins
    # Expect hist.bins() or hist.bins attribute
    if hasattr(hist, "bins"):
        bins = hist.bins
    else:
        try:
            bins = hist.bins()
        except Exception as exc:
            raise AttributeError("Histogram object must have bins() or bins attribute") from exc

    for bin_ in bins:
        # Fetch coordinate value
        if hasattr(bin_, coord_attr):
            coord = getattr(bin_, coord_attr)
        else:
            # Try methods
            if hasattr(bin_, f"get_{coord_attr}"):
                coord = getattr(bin_, f"get_{coord_attr}")()
            else:
                raise AttributeError(f"Bin object does not provide coordinate attribute/method {coord_attr}")

        # Get bin content
        if hasattr(bin_, "content"):
            content = bin_.content
        else:
            if hasattr(bin_, "data"):
                content = bin_.data
            else:
                # fall back to using bin_ itself
                content = bin_

        val = make_value(content)

        # Build point values
        if isinstance(val, (tuple, list)):
            point_vals = [coord] + list(val)
        else:
            point_vals = [coord, val]

        if len(point_vals) != len(field_names):
            raise ValueError(
                f"Point values length {len(point_vals)} does not match field_names length {len(field_names)}"
            )
        graph.add_point(*point_vals)

    # Handle scale
    if scale is True:
        if hasattr(hist, "scale"):
            graph.scale = hist.scale
        else:
            graph.scale = None
    elif scale is not None:
        graph.scale = scale

    return graph

