def hist_to_graph(hist, make_value=None, get_coordinate="left",
                   field_names=("x", "y"), scale=None):
    """Convert a :class:`.histogram` to a :class:`.graph`."""
    # Get bin edges, try common attribute names
    try:
        edges = getattr(hist, "bin_edges")
    except AttributeError:
        try:
            edges = getattr(hist, "edges")
        except AttributeError:
            raise ValueError("Histogram has no edge information")
    if len(edges) < 2:
        raise ValueError("Not enough edges to form bins")

    # Helper to obtain a bin content
    def _get_bin_content(idx):
        # try common access patterns
        if hasattr(hist, "bin"):
            return hist.bin(idx)
        if hasattr(hist, "bin_contents"):
            return hist.bin_contents[idx]
        if hasattr(hist, "__getitem__"):
            return hist[idx]
        raise ValueError("Cannot retrieve bin content")

    n_bins = len(edges) - 1
    points = []
    for i in range(n_bins):
        # determine x coordinate based on get_coordinate option
        if get_coordinate == "left":
            x_val = edges[i]
        elif get_coordinate == "right":
            x_val = edges[i + 1]
        elif get_coordinate == "middle":
            x_val = (edges[i] + edges[i + 1]) / 2.0
        else:
            raise ValueError(f"Unknown get_coordinate: {get_coordinate}")

        bin_content = _get_bin_content(i)

        # Build y values
        if make_value is None:
            y_values = (bin_content,)
        else:
            y_val = make_value(bin_content)
            if isinstance(y_val, (tuple, list)):
                y_values = tuple(y_val)
            else:
                y_values = (y_val,)

        # Combine all coordinate and y values
        full_values = (x_val,) + y_values

        if len(full_values) != len(field_names):
            raise ValueError(
                f"Number of values ({len(full_values)}) does not match "
                f"field_names ({len(field_names)})"
            )

        points.append(dict(zip(field_names, full_values)))

    # Handle scale: if scale is True, take from histogram if available
    if scale is True:
        graph_scale = getattr(hist, "scale", None)
    else:
        graph_scale = scale

    # Construct graph as a plain dict (no import or class definitions)
    return {"scale": graph_scale, "field_names": field_names, "points": points}

