def _verify(iface, candidate, tentative=False, vtype=None):
    """
    Verify that *candidate* might correctly provide *iface*.

    This involves:

    - Making sure the candidate claims that it provides the
      interface using ``iface.providedBy`` (unless *tentative* is `True`,
      in which case this step is skipped). This means that the candidate's class
      declares that it `implements <zope.interface.implementer>` the interface,
      or the candidate itself declares that it `provides <zope.interface.provider>`
      the interface

    - Making sure the candidate defines all the necessary methods

    - Making sure the methods have the correct signature (to the
      extent possible)

    - Making sure the candidate defines all the necessary attributes

    :return bool: Returns a true value if everything that could be
       checked passed.
    :raises zope.interface.Invalid: If any of the previous
       conditions does not hold.

    .. versionchanged:: 5.0
        If multiple methods or attributes are invalid, all such errors
        are collected and reported. Previously, only the first error was reported.
        As a special case, if only one such error is present, it is raised
        alone, like before.
    """
    import inspect

    errors = []

    # 1. Check that candidate claims to provide iface (unless tentative)
    if not tentative:
        try:
            if not iface.providedBy(candidate):
                errors.append(
                    f"Candidate {candidate!r} does not claim to provide {iface.__name__}"
                )
        except Exception as exc:
            errors.append(
                f"Error checking interface provision for {candidate!r}: {exc}"
            )

    # 2. Check that all required methods are provided
    #    Many zope.interface interfaces expose a ``methods`` dict of
    #    interface methods; the exact attribute name may vary.
    method_dict = getattr(iface, "methods", None)
    if method_dict is None:
        # Attempt to extract method definitions via attr inspection
        try:
            method_dict = {
                name: getattr(iface, name)
                for name in dir(iface)
                if callable(getattr(iface, name)) and not name.startswith("_")
            }
        except Exception:
            method_dict = {}

    for name, interface_method in method_dict.items():
        if not hasattr(candidate, name):
            errors.append(f"Missing method: {name}")
            continue
        candidate_method = getattr(candidate, name)
        # Simple signature check: same number of positional/keyword params
        try:
            candidate_sig = inspect.signature(candidate_method)
            interface_sig = inspect.signature(interface_method)
            if len(candidate_sig.parameters) != len(interface_sig.parameters):
                errors.append(
                    f"Method {name!r} has {len(candidate_sig.parameters)} parameters "
                    f"but interface expects {len(interface_sig.parameters)}"
                )
                continue
            # Compare each parameter kind (positional_or_keyword, var_positional, var_keyword)
            for (cname, cparam), (iname, iparam) in zip(
                candidate_sig.parameters.items(), interface_sig.parameters.items()
            ):
                if cparam.kind != iparam.kind:
                    errors.append(
                        f"Method {name!r} parameter {cname!r} kind {cparam.kind} "
                        f"does not match interface parameter {iname!r} kind {iparam.kind}"
                    )
                    break
        except Exception as exc:
            errors.append(f"Error inspecting method {name!r}: {exc}")

    # 3. Check that all required attributes are provided
    #    Some interfaces expose an ``attributes`` set or dict.
    attributes = getattr(iface, "attributes", None)
    if attributes is None:
        # Attempt to infer attribute names from the interface class
        try:
            attributes = {
                name
                for name in dir(iface)
                if not callable(getattr(iface, name))
                and not name.startswith("_")
            }
        except Exception:
            attributes = set()

    for attr in attributes:
        if not hasattr(candidate, attr):
            errors.append(f"Missing attribute: {attr}")

    # 4. Raise aggregated errors
    if errors:
        message = "; ".join(errors)
        if len(errors) == 1:
            raise vtype(message) if vtype else Exception(message)
        else:
            raise vtype(message) if vtype else Exception(message)

    return True

