    """
    Find URLs in the provided text and convert them into anchor tags with
    target="_blank" and rel="noopener noreferrer".  URLs starting with
    "www." are assumed to use http:// if no scheme is present.
    Existing anchor tags are left untouched.
    """
    import re

    # Find ranges of existing <a>...</a> to avoid double‑linkifying
    anchor_ranges = []
    for m in re.finditer(r'<a\b[^>]*>.*?</a>', text, flags=re.I | re.S):
        anchor_ranges.append((m.start(), m.end()))

    def pos_in_anchor(pos):
        for start, end in anchor_ranges:
            if start <= pos < end:
                return True
        return False

    # URL regex (simple but covers http/https and www)
    url_regex = re.compile(
        r'''
        (?P<url>
            (?:https?://|www\.)   # scheme or leading www
            [^\s<>"']+            # rest of URL
        )
        ''',
        re.IGNORECASE | re.VERBOSE
    )

    def replace(match):
        start = match.start()
        if pos_in_anchor(start):
            return match.group('url')
        url = match.group('url')
        href = url
        if url.startswith('www.'):
            href = f'http://{url}'
        return f'<a href="{href}" target="_blank" rel="noopener noreferrer">{url}</a>'

    return url_regex.sub(replace, text)

