def get_nodeinfo_well_known_document(url, document_path=None):
    """
    Generate a NodeInfo .well-known document (RFC: http://nodeinfo.diaspora.software).

    :param url: The base URL with protocol, e.g. 'https://example.com'
    :param document_path: Optional custom path for the NodeInfo document.
                          If not supplied, defaults to '/.well-known/nodeinfo'.
    :returns: A dictionary suitable for JSON serialization.
    """
    # Ensure no trailing slash on base URL
    base = url.rstrip('/')

    # Determine the path to use
    if document_path:
        path = document_path
        if not path.startswith('/'):
            path = '/' + path
        # Remove any trailing slash to avoid double slashes when appending version
        path = path.rstrip('/')
    else:
        path = '/.well-known/nodeinfo'

    # Compose the href for the current NodeInfo schema
    href = f"{base}{path}/2.0"

    # Build the well-known document content
    return {
        "links": [
            {
                "rel": "http://nodeinfo.diaspora.software/ns/schema/2.0",
                "href": href
            }
        ]
    }

