def parse_diaspora_webfinger(document: str) -> Dict:
    """Parse Diaspora webfinger which is either in JSON format (new) or XRD (old)."""
    doc = document.strip()
    if not doc:
        return {}
    # Detect JSON by first non-whitespace character
    if doc[0] in ("{", "["):
        import json
        try:
            data = json.loads(doc)
        except Exception:
            return {}
        subject = data.get("subject")
        aliases = data.get("aliases", [])
        if isinstance(aliases, str):
            aliases = [aliases]
        links = []
        links_data = data.get("links", [])
        for link in links_data:
            if not isinstance(link, dict):
                continue
            rel = link.get("rel")
            type_ = link.get("type")
            href = link.get("href")
            link_dict: Dict[str, str] = {}
            if href:
                link_dict["href"] = href
            if rel:
                link_dict["rel"] = rel
            if type_:
                link_dict["type"] = type_
            for k, v in link.items():
                if k not in ("href", "rel", "type"):
                    link_dict[k] = v
            links.append(link_dict)
        return {"subject": subject, "aliases": aliases, "links": links}
    else:
        import xml.etree.ElementTree as ET
        try:
            root = ET.fromstring(doc)
        except Exception:
            return {}
        ns = {"xrd": "http://docs.oasis-open.org/ns/xri/xrd-1.0"}
        subject_elem = root.find("xrd:subject", ns)
        subject = subject_elem.text if subject_elem is not None else None
        aliases = [e.text for e in root.findall("xrd:Alias", ns) if e.text]
        links: list[Dict[str, str]] = []
        for link_elem in root.findall("xrd:Link", ns):
            href = link_elem.attrib.get("href")
            if not href:
                continue
            link_dict: Dict[str, str] = {"href": href}
            for k, v in link_elem.attrib.items():
                if k != "href":
                    link_dict[k] = v
            links.append(link_dict)
        return {"subject": subject, "aliases": aliases, "links": links}

