def retrieve_and_parse_diaspora_webfinger(handle):
    """
    Retrieve a remote Diaspora webfinger document and parse it into a dictionary.
    If the document is JSON, it is parsed directly.
    If it is in XRD (XML) format, it is parsed into a dictionary representation.
    """
    # Ensure we have a valid handle
    if '@' not in handle:
        raise ValueError("Handle must be in the form 'user@host'")
    # Import modules locally to avoid top‑level imports
    import urllib.request
    import urllib.error
    import urllib.parse
    import json
    import xml.etree.ElementTree as ET

    # Build the WebFinger resource URL
    resource = f'acct:{handle}'
    encoded_resource = urllib.parse.quote(resource, safe='')
    # Try HTTPS first, then fallback to HTTP
    urls = (
        f'https://{handle.split("@", 1)[1]}/.well-known/webfinger?resource={encoded_resource}',
        f'http://{handle.split("@", 1)[1]}/.well-known/webfinger?resource={encoded_resource}',
    )

    for url in urls:
        try:
            req = urllib.request.Request(url, headers={'Accept': 'application/json, application/xrd+xml'})
            with urllib.request.urlopen(req, timeout=10) as resp:
                content_type = resp.headers.get('Content-Type', '')
                raw = resp.read().decode('utf-8')
        except (urllib.error.URLError, urllib.error.HTTPError):
            continue  # try the next URL
        except Exception:
            continue  # any other exception, try next

        # If content type indicates JSON or the body looks like JSON, parse JSON
        if 'application/json' in content_type or raw.lstrip().startswith('{'):
            try:
                return json.loads(raw)
            except json.JSONDecodeError:
                # If JSON parsing fails, fall back to XML parsing
                pass

        # Try parsing as XRD XML
        try:
            root = ET.fromstring(raw)
        except ET.ParseError:
            continue  # try next URL if XML parsing fails

        # Convert XML to dictionary
        def element_to_dict(elem):
            d = {}
            # Include attributes
            for k, v in elem.attrib.items():
                d[k] = v
            # Add children
            for child in elem:
                child_dict = element_to_dict(child)
                key = child.tag
                # If the same key appears multiple times, store as list
                if key in d:
                    if not isinstance(d[key], list):
                        d[key] = [d[key]]
                    d[key].append(child_dict)
                else:
                    d[key] = child_dict
            # Include text if present and there are no nested tags
            text = elem.text
            if text and not list(elem) and not elem.attrib:
                return text
            return d

        result = element_to_dict(root)
        # Wrap the result under a top-level key matching the root tag
        return {root.tag: result}

    # If all attempts fail, raise an error
    raise RuntimeError("Unable to retrieve or parse the WebFinger document for handle '{}'".format(handle))

