    except Exception as e:
        raise Exception(f'Unexpected error retrieving webfinger: {e}') from e

    try:
        return json.loads(raw)
    except json.JSONDecodeError as e:
        raise Exception('Failed to parse webfinger JSON: ' + str(e)) from e
    except Exception as e:
        raise Exception('Unexpected error parsing webfinger JSON: ' + str(e)) from e

