def retrieve_diaspora_host_meta(host):
    """
    Retrieve a remote Diaspora host-meta document.

    :arg host: Host to retrieve from
    :returns: ``XRD`` instance
    """
    import requests
    import xml.etree.ElementTree as ET
    # Normalise the host URL
    if host.startswith(('http://', 'https://')):
        base = host.rstrip('/')
    else:
        base = f"https://{host}".rstrip('/')
    url = f"{base}/.well-known/host-meta"
    try:
        resp = requests.get(url, timeout=10)
        resp.raise_for_status()
    except Exception:
        # Fallback to http when https fails or when host did not use a scheme
        scheme = 'http://'
        if base.startswith('https://'):
            other_base = base.replace('https://', scheme)
        else:
            other_base = base.replace('http://', scheme)
        url = f"{other_base.rstrip('/')}/.well-known/host-meta"
        resp = requests.get(url, timeout=10)
        resp.raise_for_status()
    # Parse the retrieved XML into an XRD instance
    try:
        return XRD.from_xml(resp.content)
    except Exception:
        root = ET.fromstring(resp.content)
