    include = cfg.pop('include', None)

    # If there's nothing to include, just return the cleaned cfg
    if not include:
        return cfg

    # Normalise include to a list of names
    if isinstance(include, str):
        include_names = [include]
    elif isinstance(include, dict):
        # Use the keys as group names; ignore mapping values
        include_names = list(include.keys())
    elif isinstance(include, (list, tuple)):
