        for k, v in group_cfg.items():
            if k in resolved_parts:
                # If duplicate keys and both values are lists, concatenate
                if isinstance(v, list) and isinstance(resolved_parts[k], list):
                    resolved_parts[k] = resolved_parts[k] + v
                else:
