    The method looks for an `include` key that can be:
    - a list of group names,
    - a dict mapping group names to a boolean flag, or
    - a single group name.

    For each group name found, the corresponding group definition is merged into
    the current dictionary. The merge is performed recursively so that nested
    dictionaries are combined cleanly. After processing the current level,
    the method recurses into any nested dictionaries or dictionaries within
    lists to resolve further include directives.

    Args:
        parser_dict (dict): The dictionary to be processed. It may contain an
            `include` key and/or a `groups` mapping.

    Returns:
        None: The input dictionary is modified in place.
    """
    # Helper to merge two dictionaries recursively
    def _deep_merge(target, source):
        for key, value in source.items():
            if (
                key in target
                and isinstance(target[key], dict)
                and isinstance(value, dict)
            ):
                _deep_merge(target[key], value)
            else:
                target[key] = value

    # If the input is not a dictionary, nothing to do
    if not isinstance(parser_dict, dict):
        return

    # Resolve include directive at the current level
    include_item = parser_dict.pop("include", None)
    if include_item:
        # Normalise to a list of group names
        if isinstance(include_item, dict):
            include_names = [name for name, flag in include_item.items() if flag]
        elif isinstance(include_item, list):
            include_names = include_item
        else:
            include_names = [include_item]

        # The groups definitions are expected to live under a "groups" key at
        # the same level. If not present, nothing will be merged.
