def _include_groups(self, parser_dict):
        """
        Resolves the `include` dict directive in the spec files.
        The directive may specify `groups` to be loaded from external
        YAML/JSON files. The loaded groups are merged into the top-level
        `groups` key in *parser_dict*. Any `include` key is removed
        after processing.
        """
        include = parser_dict.pop('include', None)
        # Nothing to do if no include directive or not a mapping
        if not isinstance(include, dict):
            return parser_dict

        inc_groups = include.get('groups')
        if not inc_groups:
            return parser_dict

        # Ensure parser_dict has a groups mapping
        if 'groups' not in parser_dict or not isinstance(parser_dict['groups'], dict):
            parser_dict['groups'] = {}

        def _merge_loaded_groups(loaded, anchor_name=None):
            """
            Merge loaded group definitions into parser_dict['groups'].
            If *anchor_name* is given and the loaded data contains a
            single group whose name matches *anchor_name*, that name
            is preserved.
            """
            if not isinstance(loaded, dict):
                return
            if anchor_name:
                # If we anchored the include to a known group name,
                # prefer that, but merge any others as well.
                if anchor_name in loaded:
                    parser_dict['groups'][anchor_name] = loaded[anchor_name]
                for name, data in loaded.items():
                    if name != anchor_name:
                        parser_dict['groups'][name] = data
            else:
                for name, data in loaded.items():
                    parser_dict['groups'][name] = data

        # Handle the various shapes of the groups specification
        if isinstance(inc_groups, list):
            for src in inc_groups:
                try:
                    loaded = self._parse_file(src)
                except Exception:
                    continue  # skip unreadable files
                _merge_loaded_groups(loaded)
        elif isinstance(inc_groups, dict):
            # Mapping from explicit group name to source file
            for name, src in inc_groups.items():
                try:
                    loaded = self._parse_file(src)
                except Exception:
                    continue
                _merge_loaded_groups(loaded, anchor_name=name)
        elif isinstance(inc_groups, str):
            try:
                loaded = self._parse_file(inc_groups)
            except Exception:
                loaded = {}
            _merge_loaded_groups(loaded)

        return parser_dict

