def create_complex_argumet_type(self, subcommand, type_name, option_name, spec_option):
    """
    Build the complex argument type.

    Parameters:
    - subcommand: the command name
    - type_name: the complex type name
    - option_name: the option name
    - spec_option: option's specifications (dict or similar)

    Returns:
    A complex type instance that can be used by the caller.
    """
    # Attempt to find a pre-defined complex type class on the instance.
    # Convention: attribute or method named "<type_name>ComplexType".
    cls = getattr(self, f"{type_name}ComplexType", None)
    if cls is not None:
        try:
            # Assume the class accepts subcommand, option_name, and keyword args from spec_option.
            return cls(subcommand=subcommand, option_name=option_name, **spec_option)
        except Exception as e:
            raise TypeError(
                f"Failed to instantiate complex type '{type_name}' with provided spec: {e}"
            ) from e

    # If no custom class is found, fall back to a simple dynamic holder.
    class _ComplexType:
        def __init__(self, subcommand, option_name, **kwargs):
            self.subcommand = subcommand
            self.option_name = option_name
            self.type_name = type_name
            for key, value in kwargs.items():
                setattr(self, key, value)

        def __repr__(self):
            attrs = ", ".join(f"{k}={v!r}" for k, v in self.__dict__.items())
            return f"<ComplexType {attrs}>"

    # Ensure spec_option is a mapping; ignore if not.
    if isinstance(spec_option, dict):
        kwargs = spec_option
    else:
        kwargs = {}
    return _ComplexType(subcommand=subcommand, option_name=option_name, **kwargs)

