def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None,
                     extra_vars=None, ansible_args=None):
    import os
    import subprocess
    import json

    # Resolve the full playbook path relative to the workspace root if necessary
    if not os.path.isabs(playbook_path):
        if ir_workspace is not None and hasattr(ir_workspace, "workspace_path"):
            base = ir_workspace.workspace_path
        else:
            base = os.getcwd()
        playbook_path = os.path.normpath(os.path.join(base, playbook_path))

    if not os.path.isfile(playbook_path):
        raise FileNotFoundError(f"Playbook not found: {playbook_path}")

    cmd = ["ansible-playbook", playbook_path]

    # Handle verbosity
    if verbose is not None:
        if isinstance(verbose, int) and verbose > 0:
            cmd.append("-" + "v" * verbose)
        else:
            # Default to -vvv if any truthy value is supplied
            cmd.append("-vvv")

    # Handle extra vars
    if extra_vars:
        try:
            extra_json = json.dumps(extra_vars)
        except (TypeError, ValueError) as e:
            raise ValueError(f"Failed to serialize extra_vars to JSON: {e}")
        cmd.extend(["--extra-vars", extra_json])

    # Handle additional ansible-playbook arguments
    if ansible_args:
        for key, value in ansible_args.items():
            key = key.lstrip("-")  # Ensure we don't duplicate dashes
            arg = f"--{key}"
            if isinstance(value, bool):
                if value:
                    cmd.append(arg)
                # skip if False
            elif isinstance(value, (list, tuple)):
                # For list-like values, split them into separate arguments
                cmd.append(arg)
                for item in value:
                    cmd.append(str(item))
            else:
                cmd.extend([arg, str(value)])

    # Execute the command using the provided plugin if available,
    # otherwise fall back to subprocess
    if ir_plugin is not None:
        # Attempt to use common Infrared plugin execution methods
        if hasattr(ir_plugin, "exec"):
            return ir_plugin.exec(cmd)
        elif hasattr(ir_plugin, "exec_cmd"):
            return ir_plugin.exec_cmd(cmd)
        elif hasattr(ir_plugin, "run"):
            return ir_plugin.run(cmd)
    # Fallback to subprocess
    return subprocess.call(cmd)

