            'force': bool,
            'name': str,
            'uuid': str
        },
        'ospd': {
            'port': int,
            'tls': bool,
            'config': str
        }
    }

    # Retrieve the mapping for this parser, defaulting to an empty dict.
    type_map = explicit_type_map.get(parser_name, {})

    # Helper functions for type coercion
    def _convert_bool(value):
        if isinstance(value, str):
            return value.lower() in ('1', 'true', 'yes', 'on')
        return bool(value)

    def _convert_int(value):
        try:
            return int(value)
        except (ValueError, TypeError):
            return value

    def _convert_float(value):
