    # Try common plugin spec file names
    for filename in ('plugin.json', 'manifest.json'):
        spec_path = os.path.join(plugin_dir, filename)
        if os.path.isfile(spec_path):
            break
    else:
        # No spec file found
        return {}

    try:
        with open(spec_path, 'r', encoding='utf-8') as f:
            data = json.load(f)
    except Exception:
        return {}

    flat = {}

    def _flatten(item, parent_key=''):
        if isinstance(item, dict):
            for k, v in item.items():
                new_key = f'{parent_key}.{k}' if parent_key else k
                _flatten(v, new_key)
        elif isinstance(item, list):
            for idx, v in enumerate(item):
                new_key = f'{parent_key}[{idx}]' if parent_key else f'[{idx}]'
                _flatten(v, new_key)
        else:
            flat[parent_key] = item

    _flatten(data)
    return flat

